import React, { useState, useEffect } from 'react';
import { Search, MapPin, Phone, User as UserIcon, Loader2, Compass, Navigation } from 'lucide-react';
import { searchDonors, searchNearbyDonors } from '../services/userService';

export default function SearchPage() {
  const [bloodGroup, setBloodGroup] = useState('');
  const [district, setDistrict] = useState('');
  const [radius, setRadius] = useState(15);
  const [donors, setDonors] = useState([]);
  const [loading, setLoading] = useState(false);
  const [useGps, setUseGps] = useState(false);
  const [gpsLoading, setGpsLoading] = useState(false);
  const [userCoords, setUserCoords] = useState(null);

  const bloodGroups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];
  const districts = ['ঢাকা', 'চট্টগ্রাম', 'রাজশাহী', 'সিলেট', 'খুলনা', 'বরিশাল', 'রংপুর', 'ময়মনসিংহ'];

  // Haversine সূত্র দিয়ে দূরত্ব (কি.মি.) হিসাব করার ফাংশন
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    if (!lat1 || !lon1 || !lat2 || !lon2) return null;
    const R = 6371; // পৃথিবীর ব্যাসার্ধ (কি.মি.)
    const dLat = ((lat2 - lat1) * Math.PI) / 180;
    const dLon = ((lon2 - lon1) * Math.PI) / 180;
    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos((lat1 * Math.PI) / 180) *
        Math.cos((lat2 * Math.PI) / 180) *
        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return (R * c).toFixed(1);
  };

  const handleSearch = async () => {
    setLoading(true);
    try {
      if (useGps) {
        setGpsLoading(true);
        navigator.geolocation.getCurrentPosition(
          async (position) => {
            const { latitude, longitude } = position.coords;
            setUserCoords({ lat: latitude, lng: longitude });
            const data = await searchNearbyDonors(latitude, longitude, radius, bloodGroup);
            setDonors(data);
            setGpsLoading(false);
            setLoading(false);
          },
          (err) => {
            alert('আপনার লাইভ লোকেশন অ্যাক্সেস পাওয়া যায়নি!');
            setGpsLoading(false);
            setLoading(false);
          }
        );
      } else {
        setUserCoords(null);
        const data = await searchDonors(bloodGroup, district);
        setDonors(data);
        setLoading(false);
      }
    } catch (err) {
      console.error('সার্চ করতে সমস্যা:', err);
      setLoading(false);
    }
  };

  useEffect(() => {
    handleSearch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [useGps]);

  return (
    <div className="max-w-2xl mx-auto px-4 py-6 space-y-6">
      
      <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm space-y-4">
        <div className="flex justify-between items-center">
          <h1 className="text-xl font-black text-slate-900">রক্তদাতা খুঁজুন</h1>
          
          <button
            onClick={() => setUseGps(!useGps)}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition flex items-center gap-1.5 ${
              useGps ? 'bg-rose-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
            }`}
          >
            <Compass className="w-4 h-4" />
            {useGps ? 'GPS ম্যাপ সার্চ চালু' : 'জেলা ফিল্টার'}
          </button>
        </div>
        
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1">রক্তের গ্রুপ</label>
            <select
              value={bloodGroup}
              onChange={(e) => setBloodGroup(e.target.value)}
              className="w-full px-3 py-2.5 rounded-xl border border-slate-200 text-xs font-bold focus:outline-none focus:border-brand-600 bg-slate-50"
            >
              <option value="">সব গ্রুপ</option>
              {bloodGroups.map((bg) => (
                <option key={bg} value={bg}>{bg}</option>
              ))}
            </select>
          </div>

          {useGps ? (
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">ব্যাসার্ধ (কি.মি.)</label>
              <select
                value={radius}
                onChange={(e) => setRadius(Number(e.target.value))}
                className="w-full px-3 py-2.5 rounded-xl border border-slate-200 text-xs font-bold focus:outline-none focus:border-brand-600 bg-slate-50"
              >
                <option value={5}>৫ কিলোমিটার</option>
                <option value={10}>১০ কিলোমিটার</option>
                <option value={20}>২০ কিলোমিটার</option>
                <option value={50}>৫০ কিলোমিটার</option>
              </select>
            </div>
          ) : (
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">জেলা</label>
              <select
                value={district}
                onChange={(e) => setDistrict(e.target.value)}
                className="w-full px-3 py-2.5 rounded-xl border border-slate-200 text-xs font-bold focus:outline-none focus:border-brand-600 bg-slate-50"
              >
                <option value="">সব জেলা</option>
                {districts.map((d) => (
                  <option key={d} value={d}>{d}</option>
                ))}
              </select>
            </div>
          )}
        </div>

        <button
          onClick={handleSearch}
          disabled={loading || gpsLoading}
          className="w-full bg-brand-600 hover:bg-brand-700 text-white py-3 rounded-xl font-bold text-xs shadow-lg shadow-brand-600/30 transition flex items-center justify-center gap-2"
        >
          {gpsLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
          {useGps ? 'কাছাকাছি রক্তদাতা খুঁজুন' : 'সার্চ করুন'}
        </button>
      </div>

      {/* Donors List */}
      {loading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 text-brand-600 animate-spin" />
        </div>
      ) : donors.length === 0 ? (
        <div className="bg-white rounded-3xl p-8 text-center border border-slate-100 shadow-sm space-y-2">
          <UserIcon className="w-10 h-10 text-slate-300 mx-auto" />
          <h3 className="text-sm font-bold text-slate-700">কোনো রক্তদাতা পাওয়া যায়নি</h3>
          <p className="text-xs text-slate-400">ফিল্টার দূরত্ব বা রক্তের গ্রুপ বদলে চেষ্টা করুন।</p>
        </div>
      ) : (
        <div className="space-y-3">
          {donors.map((donor) => {
            const distance = userCoords && donor.latitude && donor.longitude
              ? calculateDistance(userCoords.lat, userCoords.lng, donor.latitude, donor.longitude)
              : null;

            return (
              <div key={donor.id} className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-11 h-11 rounded-xl bg-rose-50 text-brand-600 font-black text-base flex items-center justify-center border border-rose-100">
                    {donor.bloodGroup}
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-slate-900">{donor.name}</h3>
                    <div className="flex items-center gap-2 text-[11px] text-slate-500 font-medium mt-0.5">
                      <span className="flex items-center gap-1">
                        <MapPin className="w-3 h-3 text-slate-400" />
                        {donor.district}
                      </span>
                      {distance && (
                        <span className="bg-rose-50 text-brand-700 px-2 py-0.5 rounded-md font-bold text-[10px] flex items-center gap-1 border border-rose-100">
                          <Navigation className="w-2.5 h-2.5" />
                          {distance} কি.মি. দূরে
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <a
                  href={`tel:${donor.phone}`}
                  className="bg-emerald-50 text-emerald-600 hover:bg-emerald-100 p-2.5 rounded-xl transition"
                >
                  <Phone className="w-4 h-4" />
                </a>
              </div>
            );
          })}
        </div>
      )}

    </div>
  );
}
